14	+final class CorporateRatePlanStrategy implements RatePlanStrategy {
15	+
16	+    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
17	+            "TECNOSUL", new BigDecimal("0.12"),
18	+            "AGROVALE", new BigDecimal("0.18"),
19	+            "FARMAVIDA", new BigDecimal("0.25")
20	+    );
21	+
22	+    @Override
23	+    public void validate(NewReservation request, Room room) {
24	+        String companyCode = request.companyCode();
25	+        if (companyCode == null || companyCode.isEmpty() || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
26	+            throw new HotelException(ErrorCode.INVALID_REQUEST, "corporate rate requires a valid company code");
27	+        }
28	+    }
29	+
30	+    @Override
31	+    public Price calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
32	+        int nights = 0;
33	+        BigDecimal subtotal = PriceCalculator.cents(BigDecimal.ZERO);
34	+        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
35	+            subtotal = subtotal.add(nightPrice(room, night));
36	+            nights++;
37	+        }
38	+        BigDecimal discountRate = COMPANY_DISCOUNTS.get(companyCode);
39	+        BigDecimal discount = PriceCalculator.cents(subtotal.multiply(discountRate));
40	+        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
41	+    }
42	+
43	+    @Override
44	+    public BigDecimal calculateRefund(BigDecimal amountPaid) {
45	+        return amountPaid;
46	+    }
