48	+    private BigDecimal nightPrice(Room room, LocalDate night) {
49	+        BigDecimal nightlyRate = room.nightlyRate();
50	+        if (PriceCalculator.isHighSeason(night)) {
51	+            return PriceCalculator.cents(nightlyRate.multiply(BigDecimal.ONE.add(PriceCalculator.HIGH_SEASON_SURCHARGE)));
52	+        }
53	+        return PriceCalculator.cents(nightlyRate);
54	+    }
